UPDATE HUB_PLAN
SET STATUS = #{status, jdbcType=VARCHAR}
WHERE TRIP_ID = #{tripId, jdbcType=VARCHAR}
RETURNING HUB_PLAN_ID

SELECT TRIP_ID
FROM HUB_PLAN
WHERE HUB_PLAN_ID = #{hubPlanId, jdbcType=VARCHAR}

SELECT HUB_PLAN_ID as "hubPlanId", TRIP_ID as "tripId", MEMBER_ID as "memberId", LIKE_COUNT as "likeCount", COPY_COUNT as "copyCount", CREATE_DATE as "createdDate" FROM HUB_PLAN WHERE STATUS = 'ACTIVE'
AND MEMBER_ID = #{memberId, jdbcType=VARCHAR}
ORDER BY LIKE_COUNT DESC
ORDER BY COPY_COUNT DESC
ORDER BY CREATE_DATE DESC
LIMIT #{size} OFFSET #{offset}
